layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){ float u = uTime - aT; if (u < 0. || u > 0.45){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 3.5; vP = position.xy*S; vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .04, -position.y*S), 1.); }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU;
    void main(){
      float r = length(vP), u = vU, f = (u < .033 ? 1.8 : 1.)*pow(max(0., 1. - u/.2), 1.5);
      float R = 3.0*(1. - pow(1. - clamp(u/.3, 0., 1.), 3.)), fr = 1. - smoothstep(.2, 0.45, u);
      vec3 o = mix(uOrange, uGold, .6)*exp(-r*r*1.2)*f*1.4 + uOrange*exp(-pow((r - R)/.08, 2.))*fr*1.2;
      o *= smoothstep(3.5, 3.3, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }
